package com.dukankhata.purchase.dto;
import com.dukankhata.purchase.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
public record PurchaseResponse(UUID id,String purchaseNumber,UUID supplierId,String supplierName,String supplierInvoiceNumber,BigDecimal subtotal,BigDecimal tax,BigDecimal total,BigDecimal paidAmount,BigDecimal payableAmount,PurchasePaymentStatus paymentStatus,String note,Instant createdAt,List<PurchaseItemResponse> items){public static PurchaseResponse from(Purchase p){return new PurchaseResponse(p.getId(),p.getPurchaseNumber(),p.getSupplier().getId(),p.getSupplier().getName(),p.getSupplierInvoiceNumber(),p.getSubtotal(),p.getTax(),p.getTotal(),p.getPaidAmount(),p.getPayableAmount(),p.getPaymentStatus(),p.getNote(),p.getCreatedAt(),p.getItems().stream().map(PurchaseItemResponse::from).toList());}}
